// Mỗi tin thoại 1 item, giữ nguyên thứ tự với nhánh 'Tin thoại?'. Lỗi tải → base64 rỗng → VOICE trả câu hỏi lại.
const src=$('Tin thoại Messenger?').all(0);
const items=$input.all();const out=[];
for(let i=0;i<items.length;i++){
 let b64='',mime='audio/mp4';
 try{const bin=items[i].binary&&items[i].binary.data;if(bin){const t=String(bin.mimeType||'').toLowerCase();mime=/^audio\/(?:mpeg|mp3|aac|ogg|wav|webm|flac|amr)$/.test(t)?t:'audio/mp4';const buf=await this.helpers.getBinaryDataBuffer(i,'data');if(buf.length<=5242880)b64=buf.toString('base64');}}catch(e){}
 out.push({json:{channel:'messenger',audioBase64:b64,mimeType:mime,messageId:src[i]?.json?.messageId||''},pairedItem:{item:i}});
}
return out;

// Ghép kết quả VOICE vào đúng tin Messenger gốc (theo thứ tự). Hiểu được → tin chữ/fast path như khách gõ; không → hỏi lại.
const src=$('Tin thoại Messenger?').all(0);
return $input.all().map((it,i)=>{
 const m=src[i].json, v=it.json||{};
 if(v.ok===true&&typeof v.text==='string'&&v.text.trim()){
  const base={...m,chatInput:v.text.slice(0,1800),heard:String(v.transcript||'').slice(0,200),memoryUserText:v.memoryUserText||v.text};
  delete base.audioUrl;
  if(v.selectedSku)return {json:{...base,mediaType:'product_detail',selectedSku:v.selectedSku,fastPath:'voice'},pairedItem:{item:i}};
  return {json:{...base,mediaType:'text'},pairedItem:{item:i}};
 }
 const r={...m,mediaType:'voice_retry',chatInput:'[Tin nhắn thoại chưa nghe rõ]',retryText:v.replyText||'Dạ shop chưa nghe được tin nhắn thoại. Mình nhắn lại bằng chữ giúp shop nhé ạ.'};
 delete r.audioUrl;
 return {json:r,pairedItem:{item:i}};
});
